import React, { useState } from 'react';
import { MapPin, Clock, Award, Search, X } from 'lucide-react';
// تأكد من أن هذا المسار صحيح حسب ترتيب المجلدات عندك
import OpportunityDetailPage from './OpportunityDetail.jsx'; 

const Opportunities = () => {
  const [filterWilaya, setFilterWilaya] = useState('');
  const [filterTech, setFilterTech] = useState('');
  
  // حالة التحكم في النافذة المنبثقة (Modal)
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedJobId, setSelectedJobId] = useState(null);

  const algeriaWilayas = ["Adrar", "Chlef", "Alger", "Constantine", "Oran", "Sétif"];
  const techs = ["React", "Java", "Python", "PHP", "Flutter"];

  const styles = {
    container: { backgroundColor: '#fdfbff', minHeight: '100vh', fontFamily: "'Segoe UI', sans-serif" },
    hero: { backgroundColor: '#c5a3d1', padding: '60px 20px', textAlign: 'center', color: 'white' },
    filterBar: { 
      backgroundColor: 'white', padding: '20px', borderRadius: '15px', 
      maxWidth: '1000px', margin: '-30px auto 40px', display: 'flex', 
      gap: '20px', boxShadow: '0 10px 25px rgba(0,0,0,0.05)', alignItems: 'flex-end' 
    },
    grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '25px', maxWidth: '1200px', margin: '0 auto', padding: '20px' },
    card: { backgroundColor: 'white', borderRadius: '15px', padding: '20px', border: '1px solid #f3e8ff', display: 'flex', flexDirection: 'column', transition: '0.3s' },
    tag: { backgroundColor: '#f3e8ff', color: '#7e22ce', padding: '4px 10px', borderRadius: '6px', fontSize: '12px', marginRight: '5px', fontWeight: '600' },
    metaInfo: { display: 'flex', flexDirection: 'column', gap: '8px', marginTop: '15px', borderTop: '1px solid #eee', paddingTop: '15px' },
    infoItem: { display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: '#555' },
    btn: { backgroundColor: '#e9d5ff', color: '#6b21a8', padding: '12px', borderRadius: '10px', border: 'none', cursor: 'pointer', marginTop: '15px', fontWeight: 'bold', width: '100%' },
    searchBtn: { backgroundColor: '#4a3f6b', color: 'white', padding: '12px 25px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' },
    // تنسيق المودال
    modalOverlay: {
      position: 'fixed', top: 0, left: 0, width: '100%', height: '100%',
      backgroundColor: 'rgba(0, 0, 0, 0.7)', display: 'flex',
      justifyContent: 'center', alignItems: 'center', zIndex: 1000,
      backdropFilter: 'blur(4px)'
    },
    modalContent: {
      backgroundColor: 'white', borderRadius: '20px', width: '90%', maxWidth: '850px',
      maxHeight: '85vh', overflowY: 'auto', position: 'relative', padding: '10px'
    },
    closeBtn: {
      position: 'absolute', top: '15px', right: '15px', backgroundColor: '#eee',
      border: 'none', borderRadius: '50%', width: '35px', height: '35px', cursor: 'pointer', zIndex: 11,
      display: 'flex', justifyContent: 'center', alignItems: 'center'
    }
  };

  const opportunitiesData = [
    { id: 1, title: "Frontend Development", company: "Tech Solutions", loc: "Constantine", dur: "3 Months", pay: "Paid" },
    { id: 2, title: "Mobile App Internship", company: "Innovation Hub", loc: "Alger", dur: "4 Months", pay: "Unpaid" }
  ];

  const handleOpenModal = (id) => {
    setSelectedJobId(id);
    setIsModalOpen(true);
  };

  return (
    <div style={styles.container}>
      <div style={styles.hero}>
        <h1 style={{ fontSize: '36px', fontWeight: 'bold', marginBottom: '10px' }}>Find Your Next Opportunity</h1>
        <p style={{ opacity: 0.9 }}>Stag.io: Connecting Students with Constantine's Best Companies.</p>
      </div>

      <div style={styles.filterBar}>
        <div style={{ flex: 1 }}>
          <label style={{ display: 'block', fontSize: '14px', marginBottom: '8px', fontWeight: '600', color: '#666' }}>Wilaya</label>
          <select 
            style={{ width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid #e5e7eb' }} 
            value={filterWilaya} 
            onChange={(e) => setFilterWilaya(e.target.value)}
          >
            <option value="">All Regions</option>
            {algeriaWilayas.map(w => <option key={w} value={w}>{w}</option>)}
          </select>
        </div>
        <div style={{ flex: 1 }}>
          <label style={{ display: 'block', fontSize: '14px', marginBottom: '8px', fontWeight: '600', color: '#666' }}>Technology</label>
          <select 
            style={{ width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid #e5e7eb' }} 
            value={filterTech} 
            onChange={(e) => setFilterTech(e.target.value)}
          >
            <option value="">All Tech</option>
            {techs.map(t => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>
        <button style={styles.searchBtn}>
          <Search size={18} style={{marginRight: '8px'}} /> Search
        </button>
      </div>

      <div style={styles.grid}>
        {opportunitiesData.map((job) => (
          <div key={job.id} style={styles.card}>
            <h3 style={{ color: '#4b2c5e', fontSize: '20px', fontWeight: 'bold', margin: '0 0 10px 0' }}>{job.title}</h3>
            <p style={{ color: '#6b7280', fontSize: '14px', marginBottom: '15px' }}>{job.company}</p>
            <div style={{ display: 'flex', gap: '5px' }}>
              <span style={styles.tag}>React</span>
              <span style={styles.tag}>Tailwind</span>
            </div>
            <div style={styles.metaInfo}>
              <div style={styles.infoItem}><MapPin size={16} color="#c5a3d1" /> {job.loc}</div>
              <div style={styles.infoItem}><Clock size={16} color="#c5a3d1" /> {job.dur}</div>
              <div style={styles.infoItem}><Award size={16} color="#c5a3d1" /> {job.pay}</div>
            </div>

            {/* الزر الصحيح لفتح المودال */}
            <button 
              onClick={() => handleOpenModal(job.id)}
              style={styles.btn}
            >
              View Details
            </button>
          </div>
        ))}
      </div>

      {/* عرض المودال فقط عند النقر */}
      {isModalOpen && (
        <div style={styles.modalOverlay} onClick={() => setIsModalOpen(false)}>
          <div style={styles.modalContent} onClick={(e) => e.stopPropagation()}>
            <button style={styles.closeBtn} onClick={() => setIsModalOpen(false)}>
              <X size={20} color="#666" />
            </button>
            {/* استدعاء محتوى التفاصيل وتمرير المعرف */}
            <OpportunityDetailPage id={selectedJobId} />
          </div>
        </div>
      )}
    </div>
  );
};

export default Opportunities;
